<?php
namespace Tests\Feature\AI;
use App\Services\AI\AiGateway;
use App\Services\AI\AiProviderInterface;
use App\Services\AI\ScribeEvidenceSummary;
use Tests\TestCase;
final class ScribeEvidenceSummaryTest extends TestCase
{
 protected function setUp():void {parent::setUp();config(['ai.enabled'=>true,'ai.clinical_enabled'=>true,'ai.clinical_clearance'=>true,'ai.paid_data_approved'=>true]);}
 private function inventory(bool $complete=true):array {return ['ok'=>true,'complete'=>$complete,'transcript'=>'Owner reports coughing.','chunks'=>[['offset'=>0,'length'=>23,'text'=>'Owner reports coughing.','status'=>$complete?'complete':'failed','segments'=>[['text'=>'Owner reports coughing.','offset'=>0,'quotes'=>[['text'=>'coughing','category'=>'subjective']]]]]]];}
 public function test_incomplete_chunks_never_generate_a_summary():void {$provider=new class implements AiProviderInterface {public int $calls=0;public function generate(string $instructions,string $message,?array $jsonSchema=null):array {$this->calls++;return ['text'=>'{}','usage'=>[]];}};$r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($this->inventory(false));self::assertTrue($r['ok']);self::assertFalse($r['complete']);self::assertNull($r['draft']);self::assertSame('incomplete_inventory',$r['code']);self::assertSame(0,$provider->calls);self::assertSame('Owner reports coughing.',$r['attention'][0]['source']);}
 public function test_unselected_source_is_visible_and_not_reported_as_complete_coverage():void {
  $inventory=['ok'=>true,'complete'=>true,'transcript'=>'Cough. Cause uncertain.','chunks'=>[['offset'=>0,'length'=>23,'text'=>'Cough. Cause uncertain.','status'=>'complete','segments'=>[['text'=>'Cough.','offset'=>0,'quotes'=>[['text'=>'Cough.','category'=>'subjective']]],['text'=>' Cause uncertain.','offset'=>6,'quotes'=>[]]]]]];
  $outputs=[['subjective'=>'Cough.','objective'=>'Not provided.','assessment'=>'Not provided.','plan'=>'Not provided.'],['claims'=>[['id'=>1,'source_ids'=>[1],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[1],'relevant'=>true,'covered'=>true]]],['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent']];
  $provider=new class($outputs) implements AiProviderInterface {public function __construct(private array $outputs){}public function generate(string $instructions,string $message,?array $jsonSchema=null):array{return ['text'=>json_encode(array_shift($this->outputs)??[]),'usage'=>[]];}};
  $r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($inventory);self::assertTrue($r['complete']);self::assertSame('unlinked_sources',$r['draftCoverage']);self::assertSame(' Cause uncertain.',$r['unlinkedSources'][0]['text']);self::assertSame(6,$r['unlinkedSources'][0]['offset']);self::assertSame('no_extracted_evidence',$r['unlinkedSources'][0]['reason']);
 }
 public function test_uncertain_evidence_remains_attached_to_its_original_passage():void {
  $inventory=['ok'=>true,'complete'=>true,'transcript'=>'Cough. Cause uncertain.','chunks'=>[['offset'=>0,'length'=>23,'text'=>'Cough. Cause uncertain.','status'=>'complete','segments'=>[['text'=>'Cough.','offset'=>0,'quotes'=>[['text'=>'Cough.','category'=>'subjective']]],['text'=>' Cause uncertain.','offset'=>6,'quotes'=>[['text'=>'Cause uncertain.','category'=>'uncertain']]]]]]];
  $outputs=[['subjective'=>'Cough.','objective'=>'Not provided.','assessment'=>'Not provided.','plan'=>'Not provided.'],['claims'=>[['id'=>1,'source_ids'=>[1],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[1],'relevant'=>true,'covered'=>true]]],['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent']];
  $provider=new class($outputs) implements AiProviderInterface {public function __construct(private array $outputs){}public function generate(string $instructions,string $message,?array $jsonSchema=null):array{return ['text'=>json_encode(array_shift($this->outputs)??[]),'usage'=>[]];}};
  $r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($inventory);self::assertSame('uncertain_classification',$r['unlinkedSources'][0]['reason']);self::assertSame('Cause uncertain.',$r['unlinkedSources'][0]['quotes'][0]['text']);self::assertSame('unlinked_sources',$r['draftCoverage']);
 }
 public function test_surrounding_whitespace_does_not_hide_a_linked_quote():void {
  $text=' First. Second.';$inventory=['ok'=>true,'complete'=>true,'transcript'=>$text,'chunks'=>[['offset'=>0,'length'=>strlen($text),'text'=>$text,'status'=>'complete','segments'=>[['text'=>' First.','offset'=>0,'quotes'=>[['text'=>' First.','category'=>'subjective']]],['text'=>' Second.','offset'=>7,'quotes'=>[['text'=>' Second.','category'=>'subjective']]]]]]];
  $outputs=[['subjective'=>'First. Second.','objective'=>'Not provided.','assessment'=>'Not provided.','plan'=>'Not provided.'],['claims'=>[['id'=>1,'source_ids'=>[1],'supported'=>true],['id'=>2,'source_ids'=>[2],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[1],'relevant'=>true,'covered'=>true],['id'=>2,'claim_ids'=>[2],'relevant'=>true,'covered'=>true]]],['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent']];
  $provider=new class($outputs) implements AiProviderInterface {public function __construct(private array $outputs){} public function generate(string $instructions,string $message,?array $jsonSchema=null):array{return ['text'=>json_encode(array_shift($this->outputs)??[]),'usage'=>[]];}};
  $r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($inventory);self::assertSame([], $r['unlinkedSources']);
 }
 public function test_answer_is_linked_when_reference_includes_preceding_question():void {
  $q='Any difficulty breathing?';$a=' Not at rest.';$text=$q.$a;
  $inventory=['ok'=>true,'complete'=>true,'transcript'=>$text,'chunks'=>[['offset'=>0,'length'=>strlen($text),'text'=>$text,'status'=>'complete','segments'=>[['text'=>$q,'offset'=>0,'quotes'=>[]],['text'=>$a,'offset'=>strlen($q),'quotes'=>[['text'=>'Not at rest.','category'=>'subjective']]]]]]];
  $outputs=[['subjective'=>'No difficulty breathing at rest.','objective'=>'Not provided.','assessment'=>'Not provided.','plan'=>'Not provided.'],['claims'=>[['id'=>1,'source_ids'=>[2],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[],'relevant'=>false,'covered'=>false],['id'=>2,'claim_ids'=>[1],'relevant'=>true,'covered'=>true]]],['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent']];
  $provider=new class($outputs) implements AiProviderInterface {public function __construct(private array $outputs){} public function generate(string $instructions,string $message,?array $jsonSchema=null):array{return ['text'=>json_encode(array_shift($this->outputs)??[]),'usage'=>[]];}};
  $r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($inventory);self::assertSame('linked',$r['claimLinks'][0]['status']);self::assertSame($text,$r['claimLinks'][0]['references'][0]['context']);self::assertNotContains($a,array_column($r['unlinkedSources'],'text'));self::assertContains($q,array_column($r['unlinkedSources'],'text'));
 }
 public function test_exact_duplicate_context_is_not_sent_twice():void {
  $text='Owner reports coughing.';$inventory=$this->inventory();
  $outputs=[['subjective'=>'Owner reports coughing.','objective'=>'Not provided.','assessment'=>'Not provided.','plan'=>'Not provided.'],['claims'=>[['id'=>1,'source_ids'=>[1],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[1],'relevant'=>true,'covered'=>true]]],['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent']];
  $provider=new class($outputs) implements AiProviderInterface {public array $messages=[];public function __construct(private array $outputs){} public function generate(string $instructions,string $message,?array $jsonSchema=null):array {$this->messages[]=json_decode($message,true);return ['text'=>json_encode(array_shift($this->outputs)??[]),'usage'=>[]];}};
  $r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($inventory);self::assertTrue($r['ok']);self::assertSame($text,$provider->messages[0]['source_context']['subjective']);self::assertSame([],$provider->messages[0]['surrounding_context']['subjective']);self::assertSame($text,$r['transcript']);
 }
 public function test_mixed_source_is_given_to_each_section_as_its_assigned_excerpt():void {
  $text='The vet said the cause was uncertain and advised follow-up.';$inventory=['ok'=>true,'complete'=>true,'transcript'=>$text,'chunks'=>[['offset'=>0,'length'=>strlen($text),'text'=>$text,'status'=>'complete','segments'=>[['text'=>$text,'offset'=>0,'quotes'=>[['text'=>'the cause was uncertain','category'=>'assessment'],['text'=>'advised follow-up','category'=>'plan']]]]]]];
  $provider=new class implements AiProviderInterface {public array $messages=[];private int $calls=0;public function generate(string $instructions,string $message,?array $jsonSchema=null):array {$this->messages[]=json_decode($message,true);$i=$this->calls++;if($i===0)$v=['subjective'=>'Not provided.','objective'=>'Not provided.','assessment'=>'cause uncertain','plan'=>'follow-up advised'];elseif($i===1)$v=['claims'=>[['id'=>1,'source_ids'=>[1],'supported'=>true],['id'=>2,'source_ids'=>[2],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[1],'relevant'=>true,'covered'=>true],['id'=>2,'claim_ids'=>[2],'relevant'=>true,'covered'=>true]]];else $v=['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent'];return ['text'=>json_encode($v),'usage'=>[]];}};
  $r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($inventory);self::assertTrue($r['ok']);self::assertSame('the cause was uncertain',$provider->messages[0]['source_context']['assessment']);self::assertSame('advised follow-up',$provider->messages[0]['source_context']['plan']);self::assertContains($text,$provider->messages[0]['surrounding_context']['assessment']);self::assertContains($text,$provider->messages[0]['surrounding_context']['plan']);self::assertSame($text,$r['claimLinks'][0]['references'][0]['context']);self::assertSame($text,$r['claimLinks'][1]['references'][0]['context']);self::assertContains('source_used_in_multiple_sections',array_column($r['attention'],'reason'));
 }
 public function test_source_used_in_multiple_sections_is_flagged():void {
  $text='Vet is uncertain and recommends follow-up.';$inventory=['ok'=>true,'complete'=>true,'transcript'=>$text,'chunks'=>[['offset'=>0,'length'=>strlen($text),'text'=>$text,'status'=>'complete','segments'=>[['text'=>$text,'offset'=>0,'quotes'=>[['text'=>'Vet is uncertain','category'=>'assessment'],['text'=>'recommends follow-up','category'=>'plan']]]]]]];
  $answers=[['subjective'=>'Not provided.','objective'=>'Not provided.','assessment'=>$text,'plan'=>$text],['claims'=>[['id'=>1,'source_ids'=>[1],'supported'=>true],['id'=>2,'source_ids'=>[2],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[1],'relevant'=>true,'covered'=>true],['id'=>2,'claim_ids'=>[2],'relevant'=>true,'covered'=>true]]],['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent']];
  $provider=new class($answers) implements AiProviderInterface {public function __construct(private array $answers){}public function generate(string $instructions,string $message,?array $jsonSchema=null):array{return ['text'=>json_encode(array_shift($this->answers)??[]),'usage'=>[]];}};
  $r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($inventory);$flags=array_values(array_filter($r['attention'],static fn($item)=>$item['reason']==='source_used_in_multiple_sections'));self::assertCount(1,$flags);self::assertSame($text,$flags[0]['source']);self::assertSame(['assessment','plan'],$flags[0]['sections']);
 }
 public function test_repeated_excerpts_are_sent_once_but_originals_stay_reviewable():void {
  $inventory=['ok'=>true,'complete'=>true,'transcript'=>'Cough. Cough.','chunks'=>[['offset'=>0,'length'=>13,'text'=>'Cough. Cough.','status'=>'complete','segments'=>[['text'=>'Cough.','offset'=>0,'quotes'=>[['text'=>'Cough.','category'=>'subjective']]],['text'=>' Cough.','offset'=>6,'quotes'=>[['text'=>'Cough.','category'=>'subjective']]]]]]];
  $answers=[['subjective'=>'Cough.','objective'=>'Not provided.','assessment'=>'Not provided.','plan'=>'Not provided.'],['claims'=>[['id'=>1,'source_ids'=>[1],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[1],'relevant'=>true,'covered'=>true]]],['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent']];
  $provider=new class($answers) implements AiProviderInterface {public array $requests=[];public function __construct(private array $answers){}public function generate(string $instructions,string $message,?array $jsonSchema=null):array {$this->requests[]=json_decode($message,true);return ['text'=>json_encode(array_shift($this->answers)??[]),'usage'=>[]];}};
  $r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($inventory);self::assertSame('Cough.',$provider->requests[0]['subjective']);self::assertArrayNotHasKey('section_evidence',$provider->requests[0]);self::assertSame('Cough.',$r['sources']['subjective']);self::assertSame('Cough. Cough.',$r['transcript']);self::assertSame('needs_review',$r['claimLinks'][0]['status']);self::assertCount(2,$r['unlinkedSources']);
 }
 public function test_repeated_source_is_not_linked_to_an_arbitrary_location():void {
  $inventory=['ok'=>true,'complete'=>true,'transcript'=>'Cough. Cough.','chunks'=>[['offset'=>0,'length'=>13,'text'=>'Cough. Cough.','status'=>'complete','segments'=>[['text'=>'Cough.','offset'=>0,'quotes'=>[['text'=>'Cough.','category'=>'subjective']]],['text'=>' Cough.','offset'=>6,'quotes'=>[['text'=>'Cough.','category'=>'subjective']]]]]]];
  $outputs=[['subjective'=>'Cough.','objective'=>'Not provided.','assessment'=>'Not provided.','plan'=>'Not provided.'],['claims'=>[['id'=>1,'source_ids'=>[1],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[1],'relevant'=>true,'covered'=>true]]],['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent']];
  $provider=new class($outputs) implements AiProviderInterface {public function __construct(private array $outputs){} public function generate(string $instructions,string $message,?array $jsonSchema=null):array{return ['text'=>json_encode(array_shift($this->outputs)??[]),'usage'=>[]];}};
  $r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($inventory);self::assertSame('needs_review',$r['claimLinks'][0]['status']);self::assertSame([],$r['claimLinks'][0]['references']);
 }
 public function test_summary_keeps_original_context_and_section_link():void {$outputs=[['subjective'=>'Owner reports cough.','objective'=>'Not provided.','assessment'=>'Not provided.','plan'=>'Not provided.'],['claims'=>[['id'=>1,'source_ids'=>[1],'supported'=>true]],'sources'=>[['id'=>1,'claim_ids'=>[1],'relevant'=>true,'covered'=>true]]],['subjective'=>'equivalent','objective'=>'equivalent','assessment'=>'equivalent','plan'=>'equivalent']];$provider=new class($outputs) implements AiProviderInterface {public function __construct(private array $outputs){}public function generate(string $instructions,string $message,?array $jsonSchema=null):array{return ['text'=>json_encode(array_shift($this->outputs)??[]),'usage'=>[]];}};$r=(new ScribeEvidenceSummary(new AiGateway($provider)))->generate($this->inventory());self::assertTrue($r['ok']);self::assertTrue($r['complete']);self::assertSame('Owner reports cough.',$r['draft']['subjective']);self::assertSame('Owner reports coughing.',$r['sources']['subjective']);self::assertSame(14,$r['evidence']['subjective'][0]['offset']);self::assertSame('linked',$r['claimLinks'][0]['status']);self::assertSame('Owner reports coughing.',$r['claimLinks'][0]['references'][0]['text']);self::assertSame(0,$r['claimLinks'][0]['references'][0]['offset']);}
}
